import Cocoa
import Sparkle

// Isolated native fixture: real Sparkle verification and installation, separate
// bundle ID/cache/key from the user's client. ProbeRoot is generated by the test.
final class UpdateFixture: NSObject, NSApplicationDelegate, SPUUpdaterDelegate {
    private var updater: SPUUpdater!
    private var window: NSWindow!
    private var timer: Timer?
    private var install: (() -> Void)?
    private var root: URL { URL(fileURLWithPath: Bundle.main.object(forInfoDictionaryKey: "ProbeRoot") as! String) }
    private func write(_ event: String) {
        let build = Bundle.main.object(forInfoDictionaryKey: "CFBundleVersion") as! String
        let data = try! JSONSerialization.data(withJSONObject: ["event": event, "build": build])
        try? data.write(to: root.appendingPathComponent("native-state.json"), options: .atomic)
        appendEvent(["event": event, "build": build])
    }
    private func appendEvent(_ event: [String: Any]) {
        let url = root.appendingPathComponent("native-events.jsonl")
        let data = try! JSONSerialization.data(withJSONObject: event)
        if !FileManager.default.fileExists(atPath: url.path) { FileManager.default.createFile(atPath: url.path, contents: nil) }
        if let handle = try? FileHandle(forWritingTo: url) {
            handle.seekToEndOfFile()
            handle.write(data)
            handle.write(Data([10]))
            try? handle.close()
        }
    }
    private func pushUpdateEvent(_ args: [String: Any]) { appendEvent(args) }
    // ProductionDownloadCallback
    func applicationDidFinishLaunching(_ notification: Notification) {
        window = NSWindow(contentRect: NSRect(x: 0, y: 0, width: 400, height: 150),
                          styleMask: [.titled, .closable], backing: .buffered, defer: false)
        window.title = "知办更新隔离验证"
        window.center()
        window.makeKeyAndOrderFront(nil)
        write("started")
        guard Bundle.main.object(forInfoDictionaryKey: "CFBundleVersion") as? String == "100" else { return }
        updater = SPUUpdater(hostBundle: Bundle.main, applicationBundle: Bundle.main,
                             userDriver: SilentUserDriver(), delegate: self)
        updater.automaticallyChecksForUpdates = false
        try! updater.start()
        updater.automaticallyDownloadsUpdates = true
        updater.checkForUpdatesInBackground()
        timer = Timer.scheduledTimer(withTimeInterval: 0.2, repeats: true) { [weak self] _ in
            guard let self else { return }
            let command = self.root.appendingPathComponent("native-command")
            guard let text = try? String(contentsOf: command, encoding: .utf8) else { return }
            try? FileManager.default.removeItem(at: command)
            if text == "quit" { NSApp.terminate(nil) }
            if text == "install", let install = self.install { install() }
        }
    }
    func feedURLString(for updater: SPUUpdater) -> String? {
        try? String(contentsOf: root.appendingPathComponent("feed-url"), encoding: .utf8)
    }
    func updater(_ updater: SPUUpdater, didFindValidUpdate item: SUAppcastItem) { write("found: \(item.versionString); auto=\(updater.automaticallyDownloadsUpdates)") }
    func updater(_ updater: SPUUpdater, didDownloadUpdate item: SUAppcastItem) { write("downloaded") }
    func updater(_ updater: SPUUpdater, willInstallUpdateOnQuit item: SUAppcastItem,
                 immediateInstallationBlock immediateInstallHandler: @escaping () -> Void) -> Bool {
        install = immediateInstallHandler
        write("ready")
        return true
    }
    func updater(_ updater: SPUUpdater, didAbortWithError error: Error) { write("failed: \(error)") }
    func updaterDidNotFindUpdate(_ updater: SPUUpdater, error: Error) { write("notFound: \(error)") }
}
let app = NSApplication.shared
let delegate = UpdateFixture()
app.delegate = delegate
app.setActivationPolicy(.regular)
app.run()
